import 'package:core_ble/core_ble.dart';

import 'protocol/glasses_order.dart';
import 'protocol/glasses_transport.dart';
import 'protocol/glasses_transport_config.dart';

/// Sends glasses protocol frames via GATT or vendor channel.
class GlassesCommandSender {
  /// Creates a command sender.
  GlassesCommandSender({
    required this.session,
    required this.config,
  });

  /// Active BLE session controller.**
  final BleSessionController session;

  /// GATT UUID configuration.**
  final GlassesTransportConfig config;

  /// Sends [frame] to the device.**
  Future<Result<void>> send(List<int> frame) async {
    if (session.useVendorChannel) {
      return session.sendVendorCommand(frame);
    }
    final link = session.connection;
    if (link == null) {
      return const Result.failure(
        AppError(code: 'glasses.not_connected', message: 'No active connection'),
      );
    }
    final transport = GlassesTransport(connection: link, config: config);
    return transport.sendFrame(frame);
  }

  /// Sends device control for audio recording.**
  Future<Result<void>> setRecording({required bool enabled}) async {
    return send(
      GlassesOrder.sendDeviceControl(
        type: GlassesOrder.controlTypeAudio,
        action: enabled ? 1 : 0,
      ),
    );
  }

  /// Sets volume 0–100.**
  Future<Result<void>> setVolume(int volume) {
    return send(GlassesOrder.sendVolume(volume));
  }

  /// Enables or disables WiFi scan on device.**
  Future<Result<void>> setWifiScan({required bool enabled}) {
    return send(GlassesOrder.switchWifiScan(isOpen: enabled));
  }
}
