  /// Advertised or platform name; may be empty.**
  final String name;

  /// Received signal strength.**
  final int rssi;

  /// Manufacturer data keyed by company id.**
  final Map<int, List<int>> manufacturerData;

  /// Display label for UI.**
  String get displayName => name.isEmpty ? id : name;

  @override
  bool operator ==(Object other) =>
      other is BleDevice &&
      other.id == id &&
      other.name == name &&
      other.rssi == rssi;

  @override
  int get hashCode => Object.hash(id, name, rssi);
}

/// High-level connection lifecycle for the active BLE link.**
enum BleConnectionState {
  /// No active connection.**
  disconnected,

  /// Connection in progress.**
  connecting,

  /// GATT link established.**
  connected,

  /// Disconnect in progress.**
  disconnecting,
}
