import 'ble_models.dart';

/// Active BLE link snapshot for UI and downstream GATT consumers.
class BleSessionState {
  /// Creates BLE session state.
  const BleSessionState({
    this.connectionState = BleConnectionState.disconnected,
    this.deviceId,
    this.deviceName,
    this.lastError,
  });

  /// Connection lifecycle.
  final BleConnectionState connectionState;

  /// Platform remote id of the active or last attempted device.
  final String? deviceId;

  /// Human-readable device label.
  final String? deviceName;

  /// Last session-level error message.
  final String? lastError;

  /// Whether GATT (or vendor) link is established.
  bool get isConnected => connectionState == BleConnectionState.connected;

  /// Short label for connection status UI.
  String get statusLabel {
    return switch (connectionState) {
      BleConnectionState.connected =>
        deviceName ?? deviceId ?? 'Connected',
      BleConnectionState.connecting => 'Connecting…',
      BleConnectionState.disconnecting => 'Disconnecting…',
      BleConnectionState.disconnected => 'Not connected',
    };
  }

  /// Returns a copy with selective overrides.
  BleSessionState copyWith({
    BleConnectionState? connectionState,
    String? deviceId,
    String? deviceName,
    String? lastError,
    bool clearError = false,
    bool clearDevice = false,
  }) {
    return BleSessionState(
      connectionState: connectionState ?? this.connectionState,
      deviceId: clearDevice ? null : (deviceId ?? this.deviceId),
      deviceName: clearDevice ? null : (deviceName ?? this.deviceName),
      lastError: clearError ? null : (lastError ?? this.lastError),
    );
  }
}
