import 'dart:async';

import 'package:core_base/core_base.dart';
import 'package:flutter_blue_plus/flutter_blue_plus.dart';

import 'ble_models.dart';
import 'ble_service.dart';

/// Default [BleService] backed by flutter_blue_plus.
class FlutterBlueBleService implements BleService {
  /// Creates the default BLE service.
  FlutterBlueBleService();

  BluetoothDevice? _activeDevice;
  StreamSubscription<BluetoothConnectionState>? _connectionSubscription;
  final _connectionStateController =
      StreamController<BleConnectionState>.broadcast();

  @override
  Stream<BleConnectionState> get connectionState =>
      _connectionStateController.stream;

  @override
  Future<Result<bool>> isAvailable() async {
    try {
      final state = await FlutterBluePlus.adapterState.first;
      return Result.success(state == BluetoothAdapterState.on);
    } on Object catch (e) {
      return Result.failure(
        AppError(
          code: 'ble.unavailable',
          message: 'Bluetooth adapter unavailable',
          cause: e,
        ),
      );
    }
  }

  @override
  Stream<BleDevice> scan({required Duration timeout}) async* {
    final available = await isAvailable();
    if (available case Failure()) {
      return;
    }
    if (available case Success(value: final on) when !on) {
      return;
    }

    try {
      await FlutterBluePlus.startScan(timeout: timeout);
    } on Object {
      return;
    }

    final seen = <String>{};
    await for (final results in FlutterBluePlus.scanResults) {
      for (final result in results) {
        final id = result.device.remoteId.str;
        if (!seen.add(id)) {
          continue;
        }
        final name = result.device.platformName.isNotEmpty
            ? result.device.platformName
            : result.advertisementData.advName;
        yield BleDevice(
          id: id,
          name: name,
          rssi: result.rssi,
          manufacturerData: result.advertisementData.manufacturerData,
        );
      }
    }
  }

  @override
  Future<Result<BleConnection>> connect(String deviceId) async {
    try {
      final device = BluetoothDevice.fromId(deviceId);
      _emitConnectionState(BleConnectionState.connecting);
      await device.connect(autoConnect: false).timeout(const Duration(seconds: 15));
      _activeDevice = device;
      await _connectionSubscription?.cancel();
      _connectionSubscription = device.connectionState.listen(_onNativeConnectionState);
      _emitConnectionState(BleConnectionState.connected);
      return Result.success(FlutterBlueBleConnection(device));
    } on TimeoutException {
      _emitConnectionState(BleConnectionState.disconnected);
      return Result.failure(
        const AppError(
          code: 'ble.connect_timeout',
          message: 'Connection timed out',
        ),
      );
    } on Object catch (e) {
      _emitConnectionState(BleConnectionState.disconnected);
      return Result.failure(
        AppError(
          code: 'ble.connect_failed',
          message: 'Failed to connect',
          cause: e,
        ),
      );
    }
  }

  @override
  Future<Result<void>> disconnect(String deviceId) async {
    try {
      _emitConnectionState(BleConnectionState.disconnecting);
      final device = _activeDevice ?? BluetoothDevice.fromId(deviceId);
      await device.disconnect();
      if (_activeDevice?.remoteId.str == deviceId) {
        _activeDevice = null;
        await _connectionSubscription?.cancel();
        _connectionSubscription = null;
      }
      _emitConnectionState(BleConnectionState.disconnected);
      return const Result.success(null);
    } on Object catch (e) {
      return Result.failure(
        AppError(
          code: 'ble.disconnect_failed',
          message: 'Failed to disconnect',
          cause: e,
        ),
      );
    }
  }

  void _onNativeConnectionState(BluetoothConnectionState state) {
    _emitConnectionState(
      state == BluetoothConnectionState.connected
          ? BleConnectionState.connected
          : BleConnectionState.disconnected,
    );
  }

  void _emitConnectionState(BleConnectionState state) {
    if (!_connectionStateController.isClosed) {
      _connectionStateController.add(state);
    }
  }
}

/// GATT session for a connected flutter_blue_plus device.
class FlutterBlueBleConnection implements BleConnection {
  /// Creates a connection wrapper for [device].
  FlutterBlueBleConnection(this._device);

  final BluetoothDevice _device;

  @override
  String get deviceId => _device.remoteId.str;

  @override
  Future<Result<List<int>>> readCharacteristic(
    String serviceUuid,
    String characteristicUuid,
  ) async {
    try {
      final characteristic = await _findCharacteristic(
        serviceUuid,
        characteristicUuid,
      );
      if (characteristic == null) {
        return Result.failure(
          const AppError(
            code: 'ble.characteristic_not_found',
            message: 'Characteristic not found',
          ),
        );
      }
      final value = await characteristic.read();
      return Result.success(value);
    } on Object catch (e) {
      return Result.failure(
        AppError(code: 'ble.read_failed', message: 'Read failed', cause: e),
      );
    }
  }

  @override
  Future<Result<void>> writeCharacteristic(
    String serviceUuid,
    String characteristicUuid,
    List<int> value, {
    bool withoutResponse = false,
  }) async {
    try {
      final characteristic = await _findCharacteristic(
        serviceUuid,
        characteristicUuid,
      );
      if (characteristic == null) {
        return Result.failure(
          const AppError(
            code: 'ble.characteristic_not_found',
            message: 'Characteristic not found',
          ),
        );
      }
      await characteristic.write(
        value,
        withoutResponse: withoutResponse,
      );
      return const Result.success(null);
    } on Object catch (e) {
      return Result.failure(
        AppError(code: 'ble.write_failed', message: 'Write failed', cause: e),
      );
    }
  }

  @override
  Stream<List<int>> notifyCharacteristic(
    String serviceUuid,
    String characteristicUuid,
  ) async* {
    final characteristic = await _findCharacteristic(
      serviceUuid,
      characteristicUuid,
    );
    if (characteristic == null) {
      return;
    }
    await characteristic.setNotifyValue(true);
    yield* characteristic.onValueReceived;
  }

  Future<BluetoothCharacteristic?> _findCharacteristic(
    String serviceUuid,
    String characteristicUuid,
  ) async {
    final services = await _device.discoverServices();
    for (final service in services) {
      if (service.uuid.str.toLowerCase() != serviceUuid.toLowerCase()) {
        continue;
      }
      for (final characteristic in service.characteristics) {
        if (characteristic.uuid.str.toLowerCase() ==
            characteristicUuid.toLowerCase()) {
          return characteristic;
        }
      }
      return null;
    }
    return null;
  }
}
